"""One related architecture suite; machine logs only, no old experiment run."""
from pathlib import Path
from datetime import datetime,timezone
import sys,os,json,subprocess,hashlib
ROOT=Path(__file__).resolve().parents[1]
stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ')
directory=ROOT/'reports/core_integration'/stamp;directory.mkdir(parents=True,exist_ok=False)
metrics=directory/'numeric_metrics.json'
environment=dict(os.environ,RETINA_NUMERIC_REPORT=str(metrics),PYTHONDONTWRITEBYTECODE='1')
command=[sys.executable,'-B','-u','-m','pytest','-q','-p','no:cacheprovider','--basetemp',str(directory/'pytest_tmp'),'tests/test_core_architecture.py','tests/test_architecture_extensions.py']
started=datetime.now(timezone.utc)
run=subprocess.run(command,cwd=ROOT,env=environment,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,encoding='utf-8',errors='replace')
(directory/'check.log').write_text(run.stdout,encoding='utf-8')
names=('spatial','assembly','components','network','mechanism_contracts','core_sources','vh2005','inner','recording','hybrid','geometry','wiring','physical','population_profiles','delays','plugins')
status={'schema_version':'core_architecture-1.0','started_utc':started.isoformat(),'finished_utc':datetime.now(timezone.utc).isoformat(),'exit_code':run.returncode,'test_suite':['tests/test_core_architecture.py','tests/test_architecture_extensions.py'],'test_result_summary':run.stdout.strip().splitlines()[-1] if run.stdout.strip() else 'no output','numeric_metrics_path':str(metrics.relative_to(ROOT)),'log_path':str((directory/'check.log').relative_to(ROOT)),'implementation_modules':{name:hashlib.sha256((ROOT/'retina_sim'/f'{name}.py').read_bytes()).hexdigest() for name in names},'preserved_reference_files':{name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest() for name in ('retina_sim/contracts.py','retina_sim/engine.py','retina_sim/provenance.py','retina_sim/reference.py','retina_sim/chen2024.py','sources/registry.json')},'implementation_scope':'Executable source-native outer route, sparse spatial assembly, required-calibration physical operators, residual BC/AC, history conductance RGC, prescribed gaze, typed ports, checkpoint and bounded streaming','synthetic_fixture_not_physiological_completion':True,'animal_data_fits_run':0,'independent_physiological_validation':'NOT_RUN','full_target_binding_status':'unbound source-specific calibrations and populations remain explicit; see numeric_metrics full_target_unbound','exact_Laguerre_solver_implemented':False,'general_nonzero_edge_delay_coupling':'IMPLEMENTED: per-edge method-of-steps, explicit prehistory/interpolation, side-aware discontinuities, bounded histories and checkpoint','multi_rate_scope':'IMPLEMENTED: explicit commensurate minimum-step scheduling with ZOH sampled outputs; arbitrary noncommensurate and mixed author-discrete coupling are rejected','rod_pathway_scope':'Typed plugin boundaries are implemented; default rod/RBC/AII physiology remains unmodeled. Engineering provider is numeric-fixture-only','mosaic_backend':'Replaceable equal-rho-mass capacitated greedy approximation, target count/quota conserved, not exact Laguerre','claims_separate':{'software_numerics':'PASS' if run.returncode==0 else 'FAIL','architecture_operators':'Implemented spatial assembly, delayed links, commensurate rates, bounded checkpoints, phenotype binding and rod-pathway plugin ABI; biological calibration independent','physiological_calibration':'NOT_COMPLETE','independent_validation':'NOT_RUN'}}
(directory/'status.json').write_text(json.dumps(status,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
(ROOT/'reports/core_architecture_status.json').write_text(json.dumps(status,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print(run.stdout,end='');print('Machine status: '+str(directory/'status.json'));sys.exit(run.returncode)
